#!/usr/bin/env node
/** Build both compiler-free distribution entries from checked TypeScript. */
import { readFile, writeFile } from 'node:fs/promises'
import { isBuiltin } from 'node:module'
import path from 'node:path'
import { fileURLToPath } from 'node:url'
import { type BuildOptions, type BuildResult, build, context, type OutputFile } from 'esbuild'

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const manifest: { name: string } = JSON.parse(
  await readFile(path.join(root, 'package.json'), 'utf8'),
)
const args = new Set(process.argv.slice(2))
const watch = args.has('--watch')
const check = args.has('--check')
const unknown = [...args].filter((arg) => arg !== '--watch' && arg !== '--check')
if (unknown.length > 0 || (watch && check)) {
  throw new Error('usage: build.ts [--watch | --check]')
}

/**
 * Runtime requests the browser artifact resolves from the host's frozen module
 * table. Both are platform seeds, so the bundle itself stays dependency-free.
 */
const CLIENT_EXTERNALS = ['react', '@deepseek-ai/dsh-client-ui-primitives']

const common: BuildOptions = {
  absWorkingDir: root,
  bundle: true,
  target: 'es2022',
  charset: 'utf8',
  legalComments: 'none',
  sourcemap: true,
  sourcesContent: true,
  metafile: true,
  write: false,
  logLevel: 'silent',
}

const targets: BuildOptions[] = [
  {
    ...common,
    entryPoints: ['src/host-entry.ts'],
    outfile: 'index.js',
    platform: 'node',
    format: 'esm',
    packages: 'external',
    banner: { js: '/* generated by scripts/build.ts — edit src/ instead */' },
  },
  {
    ...common,
    entryPoints: ['src/client-entry.ts'],
    outfile: 'client.js',
    platform: 'neutral',
    format: 'cjs',
    external: CLIENT_EXTERNALS,
    loader: { '.css': 'text' },
    banner: {
      js: `/* generated by scripts/build.ts — edit src/ instead */
window.__ModuleLoader__.load({
  id: ${JSON.stringify(manifest.name)},
  factory: (require) => {
    var module = { exports: {} };
    var exports = module.exports;
`,
    },
    footer: { js: '\n    return module.exports;\n  },\n})\n' },
  },
]

/** Reject broken wrappers, accidental runtime imports and incomplete maps. */
function validateResult(result: BuildResult): OutputFile[] {
  const outputs = result.outputFiles
  if (outputs?.length !== 2) throw new Error('expected one artifact and one source map')
  const artifact = outputs.find((file) => file.path.endsWith('.js'))
  const sourceMap = outputs.find((file) => file.path.endsWith('.js.map'))
  if (!artifact || !sourceMap || !result.metafile) throw new Error('incomplete build output')
  const name = path.basename(artifact.path)
  const text = artifact.text
  const problems: string[] = []
  if (!text.startsWith('/* generated by scripts/build.ts'))
    problems.push('missing generated banner')
  if (!text.trimEnd().endsWith(`//# sourceMappingURL=${name}.map`)) {
    problems.push('missing sourceMappingURL')
  }
  if (name === 'client.js') {
    if (!text.includes('window.__ModuleLoader__.load({'))
      problems.push('missing module loader call')
    if (!text.includes(`id: ${JSON.stringify(manifest.name)}`))
      problems.push('incorrect package id')
    if (!text.includes('return module.exports;')) problems.push('missing factory return')
    if (!text.includes('require("react")')) problems.push('React is not external')
    if (!text.includes('require("@deepseek-ai/dsh-client-ui-primitives")')) {
      problems.push('the host file-type icon request is not external')
    }
  }
  for (const output of Object.values(result.metafile.outputs)) {
    for (const dependency of output.imports) {
      const allowed =
        name === 'client.js' &&
        CLIENT_EXTERNALS.includes(dependency.path) &&
        dependency.external === true
      if (name === 'index.js' ? !isBuiltin(dependency.path) : !allowed) {
        problems.push(`unexpected runtime dependency: ${dependency.path}`)
      }
    }
  }
  const map: { sources: string[]; sourcesContent: string[] } = JSON.parse(sourceMap.text)
  if (!map.sources.length || !map.sources.some((source) => source.startsWith('src/'))) {
    problems.push('source map has no project sources')
  }
  if (map.sources.some((source) => source.includes('node_modules'))) {
    problems.push('source map contains bundled dependencies')
  }
  if (name === 'index.js' && map.sources.some((source) => !source.endsWith('.ts'))) {
    problems.push('Host source map contains non-TypeScript code')
  }
  if (map.sourcesContent.length !== map.sources.length)
    problems.push('missing embedded source content')
  if (problems.length) throw new Error(`${name}: ${problems.join('; ')}`)
  return outputs
}

/** The check path is read-only: never repair stale distribution artifacts. */
async function publish(outputs: OutputFile[]): Promise<void> {
  for (const file of outputs) {
    if (check) {
      const actual = await readFile(file.path, 'utf8').catch(() => '')
      if (actual !== file.text)
        throw new Error(`${path.basename(file.path)} is stale; run pnpm build`)
    } else {
      await writeFile(file.path, file.contents)
    }
  }
  const names = outputs.map((file) => path.basename(file.path)).join(', ')
  console.log(check ? `up to date: ${names}` : `built: ${names}`)
}

if (watch) {
  for (const options of targets) {
    const builder = await context({
      ...options,
      plugins: [
        {
          name: 'validate-and-publish',
          setup(buildContext) {
            buildContext.onEnd(async (result) => {
              if (result.errors.length) return
              try {
                await publish(validateResult(result))
                return undefined
              } catch (error) {
                return {
                  errors: [{ text: error instanceof Error ? error.message : String(error) }],
                }
              }
            })
          },
        },
      ],
    })
    await builder.watch()
  }
  console.log('watching Host and browser sources; Host changes still require a restart')
} else {
  // Build and validate both targets before writing either, avoiding partial updates on build failure.
  const results = await Promise.all(targets.map((options) => build(options)))
  const outputs = results.flatMap(validateResult)
  await publish(outputs)
}
